        test('can use custom types, operations, and security attributes', async () => {
            const project = ctx.createProject()
            const fluentFile = project.addFile({
                path: 'acls.now.ts',
                content: `
import { Acl } from '@servicenow/sdk/core'
Acl({
    $id: Now.ID['test_acl'],
    operation: 'aaaaaaaabbbbbbbbccccccccdddddddd', // custom operation
    type: 'ffffffffaaaaaaaaddddddddeeeeeeee', // custom type
    table: 'task',
    securityAttribute: 'a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1', // custom security attribute
})`,
            })

            const diagnostics = (await fluentFile.getDiagnostics()).map((d) => d.message)
            expect(diagnostics).toEqual([])

            const database = await fluentFile.getRecords()
            const aclRecord = database.query()[0]

            expect(aclRecord.getValue()).toMatchObject({
                operation: 'aaaaaaaabbbbbbbbccccccccdddddddd',
                type: 'ffffffffaaaaaaaaddddddddeeeeeeee',
                security_attribute: 'a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1',
            })
        })

