        test(`DEF0722687: Acl plugin works with multiple roles`, async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'acls.now.ts',
                content: `
import { Acl } from '@servicenow/sdk/core'

Acl({
    $id: Now.ID['incident_read'],
    operation: 'read',
    type: 'record',
    table: 'incident',
    roles: ['admin', 'aisa_admin']
})`,
            })

            const diagnostics = (await file.getDiagnostics()).map((d) => d.message)
            expect(diagnostics).toEqual([])

            const files = await file.getOutput()
            const roleM2ms = files.filter((f) => f.path.includes('sys_security_acl_role')).map((f) => f.content)

            expect(roleM2ms).toHaveLength(2)
            expect(roleM2ms).toEqual(
                expect.arrayContaining([
                    expect.stringMatching('<sys_user_role name="admin">.*</sys_user_role>'),
                    expect.stringMatching('<sys_user_role name="aisa_admin">.*</sys_user_role>'),
                ])
            )
        })

        test('Convert ACL with glue code to module with params', async () => {
            const project = createProject({ rootDir: __dirname })
            project.addFile({
                content: `export function myGlueCode(current: string, extraParam: string): boolean {
    return current.getValue('field') === extraParam;
}`,
                path: 'src/server/my-glue-code.js',
            })
            const sourceFile = project.addFile({
                content: `import { Acl } from '@servicenow/sdk/core'
import { myGlueCode } from '../server/my-glue-code.js'
Acl({
    $id: Now.ID['01e1762a772ec210ce35f6992c5a9996'],
    type: 'record',
    operation: 'create',
    roles: ['x_test.admin'],
    table: 'x_test_my_table',
    field: 'type',
    script: myGlueCode
})
                `,
                path: 'src/fluent/acl.now.ts',
            })

            const diagnostics = (await sourceFile.getDiagnostics()).map((d) => d.message)
            expect(diagnostics).toEqual([])

            const acl = (await sourceFile.getRecords()).query('sys_security_acl')[0]
            expect(acl.get('script').getValue()).toContain('answer = myGlueCode(current, extraParam)')
        })

